(() => {
  const pageConfig = document.querySelector('#thesisDefenseConfig');
  const bar = document.querySelector('[data-defense-schedule]');
  const modal = document.querySelector('[data-defense-schedule-modal]');
  const periodFilter = document.querySelector('[data-tm-period]');
  if (!pageConfig || !bar || !modal || !pageConfig.dataset.scheduleSave) return;
  let schedules = JSON.parse(bar.dataset.schedules || '{}');
  const defaultPeriod = document.querySelector('[data-defense-schedule-period-default]')?.dataset.defenseSchedulePeriodDefault || '';
  let activePeriod = periodFilter?.value || defaultPeriod || Object.keys(schedules)[0] || '';
  const form = modal.querySelector('[data-defense-schedule-form]');
  const updateBar = () => { const item=schedules[String(activePeriod)]||{}; const date=item.defense_date||'Fecha sin definir'; const time=item.defense_time || 'Hora sin definir'; bar.querySelector('[data-defense-schedule-status]').textContent=(item.defense_date||item.defense_time)?`${date} · ${time}`:'Fecha y hora sin definir'; bar.querySelector('[data-defense-schedule-open]').textContent=(item.defense_date||item.defense_time)?'Editar programación':'Programar jornada'; };
  const open = () => { const item=schedules[String(activePeriod)]||{}; form.defense_date.value=item.defense_date||''; form.defense_time.value=(item.defense_time||'').slice(0,5); modal.hidden=false; document.body.classList.add('tm-modal-open'); modal.querySelector('[data-defense-schedule-dialog]').focus(); };
  const close = () => { modal.hidden=true; document.body.classList.remove('tm-modal-open'); };
  bar.querySelector('[data-defense-schedule-open]').addEventListener('click',open);
  modal.querySelectorAll('[data-defense-schedule-close],[data-defense-schedule-cancel]').forEach(button=>button.addEventListener('click',close));
  modal.addEventListener('click',event=>{if(event.target===modal)close();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close();});
  periodFilter?.addEventListener('change',()=>{activePeriod=periodFilter.value||defaultPeriod||Object.keys(schedules)[0]||'';updateBar();});
  form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[data-defense-schedule-save]'),error=form.querySelector('[data-defense-schedule-error]');if(!activePeriod||Number(activePeriod)<1){error.textContent='No se pudo identificar el período académico seleccionado.';error.hidden=false;return;}button.disabled=true;error.hidden=true;const body=new FormData(form);body.set('_csrf',pageConfig.dataset.csrf||'');body.set('academic_period_id',activePeriod);try{const response=await fetch(pageConfig.dataset.scheduleSave,{method:'POST',body,headers:{Accept:'application/json'}}),json=await response.json();if(!response.ok||!json.success)throw new Error(json.message||'No fue posible guardar la programación.');if(json.data?.schedule)schedules[String(activePeriod)]=json.data.schedule;else delete schedules[String(activePeriod)];updateBar();close();}catch(errorValue){error.textContent=errorValue.message;error.hidden=false;}finally{button.disabled=false;}});
  updateBar();
})();

