(() => {
  const config = document.querySelector('#thesisDefenseConfig');
  const schedule = document.querySelector('[data-defense-schedule]');
  if (!config || !schedule || !config.dataset.scheduleSave) return;

  const form = schedule.querySelector('[data-defense-schedule-form]');
  const period = schedule.querySelector('[data-defense-schedule-period]');
  const date = form?.elements.defense_date;
  const time = form?.elements.defense_time;
  const error = schedule.querySelector('[data-defense-schedule-error]');
  const feedback = schedule.querySelector('[data-defense-schedule-feedback]');
  const save = schedule.querySelector('[data-defense-schedule-save]');
  let schedules = {};
  try { schedules = JSON.parse(config.dataset.schedules || '{}'); } catch (_) { schedules = {}; }
  const render = () => {
    const item = schedules[String(period?.value || '')] || {};
    if (date) date.value = item.defense_date || '';
    if (time) time.value = (item.defense_time || '').slice(0, 5);
    if (error) error.hidden = true;
    if (feedback) feedback.hidden = true;
  };
  const mainPeriod = document.querySelector('[data-tm-period]');
  if (mainPeriod && period) mainPeriod.addEventListener('change', () => {
    if (mainPeriod.value && String(period.value) !== String(mainPeriod.value)) {
      period.value = mainPeriod.value;
      render();
    }
  });
  period?.addEventListener('change', () => {
    if (mainPeriod && String(mainPeriod.value) !== String(period.value)) {
      mainPeriod.value = period.value;
      mainPeriod.dispatchEvent(new Event('change'));
    }
    render();
  });
  form?.addEventListener('submit', async event => {
    event.preventDefault();
    if (!period?.value || !save || save.disabled) return;
    save.disabled = true;
    if (error) error.hidden = true;
    if (feedback) feedback.hidden = true;
    const body = new FormData(form);
    body.set('_csrf', config.dataset.csrf || '');
    try {
      const response = await fetch(config.dataset.scheduleSave, { method: 'POST', body, headers: { Accept: 'application/json' } });
      const json = await response.json();
      if (!response.ok || !json.success) throw new Error(json.message || 'No fue posible guardar la programación global de defensa.');
      const id = String(period.value);
      if (json.data?.schedule) schedules[id] = json.data.schedule;
      else delete schedules[id];
      render();
      if (feedback) { feedback.textContent = json.message; feedback.hidden = false; }
    } catch (exception) {
      if (error) { error.textContent = exception.message; error.hidden = false; }
    } finally { save.disabled = false; }
  });
})();

