document.addEventListener('click', event => { const modal = document.querySelector('[data-new-attempt-modal]'); if (modal && !modal.hidden && event.target === modal) modal.querySelector('[data-new-attempt-cancel]')?.click(); });

document.addEventListener('click', event => { const trigger=event.target.closest('[data-defense-new-attempt]'); if(!trigger)return; window.setTimeout(()=>{const modal=document.querySelector('[data-new-attempt-modal]'),body=modal?.querySelector('.tm-modal-body'); if(!modal||!body)return; const old=body.querySelector('dl'); if(old)old.hidden=true; body.querySelectorAll(':scope > p:not([data-new-attempt-error])').forEach(node=>{if(!node.closest('[data-new-attempt-visual]'))node.hidden=true;}); let panel=body.querySelector('[data-new-attempt-visual]'); if(!panel){panel=document.createElement('div');panel.dataset.newAttemptVisual='';panel.innerHTML='<p class="tm-info-notice tm-attempt-info"><i class="fa-solid fa-circle-info" aria-hidden="true"></i><span>El resultado de la defensa anterior permanecerá en el historial. Se habilitará un nuevo intento para continuar el proceso.</span></p><div class="tm-attempt-transition"><div><strong></strong><span>No aprobado</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><strong></strong><span>Nuevo intento</span></div></div><section class="tm-retained-tribunal"><h3>Tribunal que Se conservará</h3><ul></ul></section><p class="tm-defense-warning"><span>El Tribunal actual Se conservará para la nueva defensa. Si necesitas modificarlo, hazlo desde Cambiar Tribunal.</span></p>';body.prepend(panel);} const strongs=panel.querySelectorAll('strong');strongs[0].textContent=`Defensa ${trigger.dataset.attempt}`;strongs[1].textContent=`Defensa ${Number(trigger.dataset.attempt)+1}`;const list=panel.querySelector('ul');list.replaceChildren(...JSON.parse(trigger.dataset.tribunalNames||'[]').map(name=>Object.assign(document.createElement('li'),{textContent:name})));},0); });
document.addEventListener('click',event=>{const modal=document.querySelector('[data-new-attempt-modal]');const save=event.target.closest('[data-new-attempt-save]');if(!modal||!save||modal.hidden||save.dataset.confirmed)return;event.preventDefault();event.stopImmediatePropagation();if(document.querySelector('[data-new-attempt-confirm]'))return;const box=document.createElement('div');box.className='tm-modal tm-attempt-confirm';box.dataset.newAttemptConfirm='1';box.innerHTML='<section role="dialog" aria-modal="true"><header><h2>Confirmar nueva defensa</h2><button type="button" aria-label="Cerrar" data-close><i class="fa-solid fa-xmark" aria-hidden="true"></i></button></header><div class="tm-modal-body"><p>Se creará la siguiente defensa.</p><p><strong>Intento anterior:</strong> '+(modal.querySelector('[data-new-attempt-current]')?.textContent||'')+' · No aprobado</p><p><strong>Nuevo intento:</strong> '+(modal.querySelector('[data-new-attempt-next]')?.textContent||'')+'</p><p><strong>Tribunal:</strong> Se conservará el Tribunal actual.</p><p class="tm-defense-warning"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i>El resultado anterior permanecerá en el historial y no ser&aacute; modificado.</p></div><footer><button type="button" data-close>Volver</button><button type="button" class="tm-primary-action" data-confirm>Confirmar nueva defensa</button></footer></section>';document.body.append(box);const close=()=>box.remove();box.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',close));box.addEventListener('click',e=>{if(e.target===box)close();});box.querySelector('[data-confirm]').addEventListener('click',()=>{close();save.dataset.confirmed='1';save.click();delete save.dataset.confirmed;});},true);
